import type { ArticleCategory, ArticleDifficulty } from "../src/generated/prisma/enums";

type Option = { id: string; text: string };
type Question = {
  type: "MULTIPLE_CHOICE" | "TRUE_FALSE_NOT_GIVEN" | "SENTENCE_COMPLETION" | "SHORT_ANSWER";
  prompt: string;
  evidenceBlockIndex: number;
  passageBlockIndex?: number;
  options?: Option[];
  correctAnswers: string[];
  explanation: string;
};
type Article = {
  title: string;
  slug: string;
  description: string;
  category: ArticleCategory;
  difficulty: ArticleDifficulty;
  blocks: [type: "heading" | "paragraph", text: string][];
  questions: Question[];
};

const choice = (prompt: string, labels: string[], answer: string, evidenceBlockIndex: number, explanation: string): Question => ({
  type: "MULTIPLE_CHOICE",
  prompt,
  options: labels.map((text, index) => ({ id: String.fromCharCode(65 + index), text })),
  correctAnswers: [answer],
  evidenceBlockIndex,
  explanation,
});
const trueFalse = (prompt: string, answer: string, evidenceBlockIndex: number, explanation: string): Question => ({
  type: "TRUE_FALSE_NOT_GIVEN",
  prompt,
  options: [{ id: "TRUE", text: "TRUE" }, { id: "FALSE", text: "FALSE" }, { id: "NOT_GIVEN", text: "NOT GIVEN" }],
  correctAnswers: [answer],
  evidenceBlockIndex,
  explanation,
});
const completion = (prompt: string, answer: string, evidenceBlockIndex: number, explanation: string): Question => ({
  type: "SENTENCE_COMPLETION",
  prompt,
  correctAnswers: [answer],
  evidenceBlockIndex,
  explanation,
});
const shortAnswer = (prompt: string, answer: string, evidenceBlockIndex: number, explanation: string): Question => ({
  type: "SHORT_ANSWER",
  prompt,
  correctAnswers: [answer],
  evidenceBlockIndex,
  explanation,
});

